getAssignmentGroupForCaller(callerSysId) {
  var caller = new GlideRecord('sys_user');
  caller.get(callerSysId);
  var domain = caller.getValue('sys_domain');

  var map = new GlideRecord('u_domain_service_desk_group');
  map.addQuery('u_domain', domain);
  map.query();

  return map.next()
    ? map.getValue('u_assignment_group')
    : gs.getProperty('u_default_service_desk_group');
}

getApproverForAccessRequest(requestedForId) {
  var user = new GlideRecord('sys_user');
  user.get(requestedForId);
  var manager = user.manager;

  if (manager.sys_domain != user.sys_domain) {
    gs.error('Cross-domain manager mismatch');
    return null; // fail closed
  }
  return manager.sys_id.toString();
}
